import pytest

from wallace import wallace_tm


def test_lowercase_is_case_insensitive():
    assert wallace_tm('atgc') == 12


def test_rejects_invalid_base_and_names_it():
    with pytest.raises(ValueError, match='X'):
        wallace_tm('ATXG')


def test_known_answer_basic():
    assert wallace_tm('ATGC') == 12


def test_known_answer_longer():
    # 10 GC pairs -> 4*10 = 40; no AT
    assert wallace_tm('AGCTAGCTAGCTAGCTAGCT') == 60

_VALID_BASES = set('ACGT')


def wallace_tm(seq):
    """Wallace rule melting temperature: Tm = 2*(A+T) + 4*(G+C).

    Case-insensitive; raises ValueError on any non-ACGT character.
    """
    s = seq.upper()
    invalid = set(s) - _VALID_BASES
    if invalid:
        raise ValueError(
            f"Invalid nucleotide(s) in sequence: {', '.join(sorted(invalid))}"
        )
    return 2 * (s.count('A') + s.count('T')) + 4 * (s.count('G') + s.count('C'))
